package com.kafka.backend.money;
import org.junit.jupiter.api.Test;
import com.kafka.backend.common.InvalidRequestException;
import static org.assertj.core.api.Assertions.*;
class MoneyCalendarTest {
 @Test void directPayIsAuthoritativeAndIncludedIncentiveMustFit(){assertThat(MoneyCalendarService.directDailyPay(38410L,2000L)).isEqualTo(38410);assertThat(MoneyCalendarService.directDailyPay(38410L,0L)).isEqualTo(38410);assertThat(MoneyCalendarService.directDailyPay(0L,0L)).isZero();for(Long incentive:new Long[]{-1L,38411L,null})assertThatThrownBy(()->MoneyCalendarService.directDailyPay(38410L,incentive)).isInstanceOf(InvalidRequestException.class);}
 @Test void legacyEligibilityExcludesNonworkingArchivedConfirmedAndUpcomingWork(){
  var today=java.time.LocalDate.of(2026,10,17);var row=new java.util.LinkedHashMap<String,Object>();row.put("workDate","2026-10-02");row.put("status","COMPLETED");assertThat(MoneyCalendarService.legacyReviewRequired(row,today)).isTrue();
  for(String status:new String[]{"OFF","CANCELLED"}){row.put("status",status);assertThat(MoneyCalendarService.legacyReviewRequired(row,today)).isFalse();}row.put("status","SCHEDULED");assertThat(MoneyCalendarService.legacyReviewRequired(row,today)).isTrue();
  row.put("removed",true);assertThat(MoneyCalendarService.legacyReviewRequired(row,today)).isFalse();row.put("removed",false);row.put("workDate",today.toString());assertThat(MoneyCalendarService.legacyReviewRequired(row,today)).isFalse();row.put("status","COMPLETED");assertThat(MoneyCalendarService.legacyReviewRequired(row,today)).isTrue();row.put("workDate",today.plusDays(1).toString());assertThat(MoneyCalendarService.legacyReviewRequired(row,today)).isFalse();
  row.put("workDate","2026-10-02");row.put("wageModel","CONFIRMED_V2");row.put("basePay",42520L);row.put("dailyIncentive",0L);row.put("totalDeduction",4110L);row.put("confirmedDailyPay",38410L);assertThat(MoneyCalendarService.confirmedEarnings(row)).isTrue();assertThat(MoneyCalendarService.legacyReviewRequired(row,today)).isFalse();row.put("basePay",0L);row.put("dailyIncentive",500L);row.put("totalDeduction",400L);row.put("confirmedDailyPay",100L);assertThat(MoneyCalendarService.confirmedEarnings(row)).isTrue();row.put("wageModel","CONFIRMED_DIRECT_V3");row.put("confirmedDailyPay",38410L);row.put("dailyIncentive",2000L);assertThat(MoneyCalendarService.confirmedEarnings(row)).isTrue();assertThat(MoneyCalendarService.legacyReviewRequired(row,today)).isFalse();
 }
 @Test void confirmedDailyComponentsAndBoundaries(){assertThat(MoneyCalendarService.confirmedDailyPay(60000L,5000L,1000L)).isEqualTo(64000);assertThat(MoneyCalendarService.confirmedDailyPay(0L,0L,0L)).isZero();assertThat(MoneyCalendarService.confirmedDailyPay(999999999999L,1L,1L)).isEqualTo(999999999999L);assertThatThrownBy(()->MoneyCalendarService.confirmedDailyPay(999999999999L,1L,0L)).isInstanceOf(InvalidRequestException.class);assertThatThrownBy(()->MoneyCalendarService.confirmedDailyPay(0L,0L,1L)).isInstanceOf(InvalidRequestException.class);}
 @Test void allVisibleMonthGridsAreCompleteSundaySaturdayWeeks(){for(int year=2025;year<=2027;year++)for(int month=1;month<=12;month++){var m=java.time.YearMonth.of(year,month);var range=MoneyCalendarService.visibleRange(m.toString());assertThat(range[0].getDayOfWeek()).isEqualTo(java.time.DayOfWeek.SUNDAY);assertThat(range[1].getDayOfWeek()).isEqualTo(java.time.DayOfWeek.SATURDAY);assertThat(java.time.temporal.ChronoUnit.DAYS.between(range[0],range[1])+1).isIn(28L,35L,42L);assertThat(range[0]).isBeforeOrEqualTo(m.atDay(1));assertThat(range[1]).isAfterOrEqualTo(m.atEndOfMonth());}}
 @Test void overnightAndBreakDuration(){assertThat(MoneyCalendarService.duration("22:00","02:30",true,30)).isEqualTo(240);assertThat(MoneyCalendarService.duration("09:00","18:00",false,60)).isEqualTo(480);}
 @Test void invalidOrAmbiguousIntervalsRejected(){for(var times:new String[][]{{"22:00","02:00"},{"09:00","09:00"}})assertThatThrownBy(()->MoneyCalendarService.duration(times[0],times[1],false,0)).isInstanceOf(InvalidRequestException.class);assertThatThrownBy(()->MoneyCalendarService.duration("09:00","18:00",true,0)).isInstanceOf(InvalidRequestException.class);assertThatThrownBy(()->MoneyCalendarService.duration("09:00","10:00",false,60)).isInstanceOf(InvalidRequestException.class);}
}
